@Composable
fun AccountActionScreen(
    onContinue: () -> Unit,
    onCancel: () -> Unit
) {
    var isSubmitting by remember { mutableStateOf(false) }

    FrogTheme {
        Surface(
            modifier = Modifier.fillMaxSize(),
            color = FrogTheme.colors.background
        ) {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(FrogTheme.spacing.xl),
                verticalArrangement = Arrangement.spacedBy(FrogTheme.spacing.lg)
            ) {
                Text(
                    text = "Confirm Operation",
                    style = FrogTheme.typography.title,
                    color = FrogTheme.colors.foreground
                )
                Text(
                    text = "Your action will immediately take effect across all synced workspaces.",
                    style = FrogTheme.typography.body,
                    color = FrogTheme.colors.mutedForeground
                )
                Spacer(modifier = Modifier.weight(1f))
                FrogButton(
                    onClick = {
                        isSubmitting = true
                        onContinue()
                    },
                    loading = isSubmitting,
                    variant = FrogButtonVariant.Primary,
                    fullWidth = true
                ) {
                    Text("Confirm & Proceed")
                }
                FrogButton(
                    onClick = onCancel,
                    variant = FrogButtonVariant.Ghost,
                    fullWidth = true,
                    enabled = !isSubmitting
                ) {
                    Text("Cancel")
                }
            }
        }
    }
}

