@Composable
fun ExpandableCard(expanded: Boolean) {
    val motion = FrogTheme.motion
    val rotation by animateFloatAsState(
        targetValue = if (expanded) 180f else 0f,
        animationSpec = motion.normalSpec(),
        label = "ChevronRotation"
    )

    AnimatedVisibility(
        visible = expanded,
        enter = fadeIn(animationSpec = motion.fastSpec()) + expandVertically(animationSpec = motion.normalSpec()),
        exit = fadeOut(animationSpec = motion.fastSpec()) + shrinkVertically(animationSpec = motion.normalSpec())
    ) {
        CardContent()
    }
}

@Composable
fun AccessibleIconButton(
    onClick: () -> Unit,
    icon: ImageVector,
    contentDescription: String
) {
    val sizing = FrogTheme.sizing

    Box(
        modifier = Modifier
            .size(sizing.minimumTouchTarget) // 48dp interactive envelope
            .clickable(onClick = onClick),
        contentAlignment = Alignment.Center
    ) {
        Box(
            modifier = Modifier
                .size(sizing.controlSmall) // 32dp visual pill
                .background(FrogTheme.colors.subtleSurface, FrogTheme.shapes.full),
            contentAlignment = Alignment.Center
        ) {
            Icon(
                imageVector = icon,
                contentDescription = contentDescription,
                modifier = Modifier.size(sizing.iconSmall),
                tint = FrogTheme.colors.foreground
            )
        }
    }
}

