@Composable
fun AdaptiveDashboard() {
    BoxWithConstraints(modifier = Modifier.fillMaxSize()) {
        val windowClass = FrogTheme.adaptive.windowSizeClass(maxWidth)

        when (windowClass) {
            FrogWindowSizeClass.Compact -> {
                // Single column phone layout
                PhoneDashboardLayout()
            }
            FrogWindowSizeClass.Medium -> {
                // Navigation rail + content
                Row(modifier = Modifier.fillMaxSize()) {
                    DashboardNavRail()
                    PhoneDashboardLayout(modifier = Modifier.weight(1f))
                }
            }
            FrogWindowSizeClass.Expanded -> {
                // Multi-pane: Sidebar + Content + Inspector
                Row(modifier = Modifier.fillMaxSize()) {
                    DashboardSidebar(modifier = Modifier.width(260.dp))
                    PrimaryContentPane(modifier = Modifier.weight(1f))
                    InspectorPane(modifier = Modifier.width(360.dp))
                }
            }
        }
    }
}

